    "degree": 0.20,
    "gaps_in_employment": 0.15,
    "age": 0.15,
    "postcode": 0.10,
}

EXPERIENCE_SCORES = {
    "none": 0,
    "entry": 25,
    "early_career": 50,
    "mid": 70,
    "senior": 85,
    "expert": 100,
}

DEGREE_SCORES = {
    "none": 0,
    "high_school": 20,
    "some_college": 40,
    "bachelors": 60,
    "masters": 75,
    "doctorate": 90,
}

GAP_SCORES = {
    "none": 100,
    "short": 80,
    "moderate": 60,
    "long": 40,
}

AGE_SCORES = {
    "under_25": 50,
    "25_to_40": 70,
    "41_to_60": 85,
    "over_60": 100,
}


def normalize(score: float, min_score: float = 0, max_score: float = 100) -> float:
    """Scale a score to the 0-100 range."""
    if max_score == min_score:
        return 0
    return min(100, max(0, (score - min_score) / (max_score - min_score) * 100))


def score_candidate(candidate: Dict[str, Any], weights: Dict[str, float] = None) -> Dict[str, Any]:
    if weights is None:
        weights = dict(DEFAULT_WEIGHTS)

    total = 0.0
    details = {}

    for field in CANDIDATE_FIELDS:
        value = candidate.get(field)
        weight = weights.get(field, 0)

        if field == "years_experience":
            score = EXPERIENCE_SCORES.get(value, 0)
        elif field == "degree":
            score = DEGREE_SCORES.get(value, 0)
        elif field == "gaps_in_employment":
            score = GAP_SCORES.get(value, 100)
        elif field == "age":
            score = AGE_SCORES.get(value, 50)
        elif field == "postcode":
            score = 50  # no evidence that a postcode predicts the job
        else:
            score = 0

        normalized = normalize(score)
        total += normalized * weight
        details[field] = {"raw": score, "normalized": normalized, "weight": weight}

    details["total"] = total
    return details
```

