import math

RANK_ORDER = {
    "none": 0,
    "undergraduate": 1,
    "professional": 2,
    "postgraduate": 3,
}

CAREER_FIELD = {
    "retail": ["retail", "sales", "shop", "counter"],
    "healthcare": ["nurse", "doctor", "care", "patient", "therapy"],
    "tech": ["engineer", "developer", "software", "it", "support"],
}

CAREER_KEYS = ["current_role", "previous_roles", "industry"]
ROLE_KEYS = ["job_title", "position", "role"]

def _match_field(text, field_type):
    """Return the index of the first career field that matches text, or -1."""
    text = (text or "").lower()
    for i, keywords in enumerate(CAREER_FIELD.get(field_type, [])):
        if keywords in text:
            return i
    return -1

def _years_experience(cv):
    exp = cv.get("years_experience", 0)
    if not isinstance(exp, (int, float)):
        try:
            exp = float(exp.split("-")[0])
        except (ValueError, TypeError):
            return 0
    return max(0, exp)

def _degree_score(cv):
    deg = cv.get("degree", "").lower()
    if "postgraduate" in deg or "masters" in deg or "doctor" in deg:
        return RANK_ORDER["postgraduate"]
    if "professional" in deg:
        return RANK_ORDER["professional"]
    if "undergraduate" in deg or "bachelor" in deg:
        return RANK_ORDER["undergraduate"]
    return RANK_ORDER["none"]

def _recent_role(cv):
    """The most recent role, or the role closest to now from the history."""
    for key in CAREER_KEYS:
        if key in cv:
            return cv[key]
    for key in ROLE_KEYS:
        if key in cv:
            return cv[key]
    return None

def score_cv(cv):
    score = 0
    cv = dict(cv)
    cv["years_experience"] = _years_experience(cv)
    cv["degree_score"] = _degree_score(cv)
    cv["current_role"] = _recent_role(cv)
    cv["career_field"] = [
        k for k, v in CAREER_FIELD.items() if any(_match_field(cv["current_role"], k) >= 0 for k in CAREER_FIELD)
    ]
    return score
