Here's the function. Read the note below it before you let it score anyone.

```python
import re
from datetime import date

CITY_CODES = {
    "north": ["M", "LS", "BD", "HX", "BB", "WN"],
    "south": ["SW", "SE", "BR"],
    "central": ["B", "N", "S", "W"],
}


def parse_postcode(postcode):
    """Return the outward code, e.g. 'M1' from 'M1 4BN'."""
    if not isinstance(postcode, str):
        return None
    parts = postcode.strip().split()
    if not parts:
        return None
    outer = re.sub(r"\d", "", parts[0])
    return outer.upper() if outer else None


def score_applicant(
    years_experience=None,
    degree=None,
    age=None,
    gaps_in_employment=None,
    postcode=None,
):
    """Score an applicant from 0 to 100.

    Fields that are missing or clearly junk get a neutral score of 50.
    Each field is capped at 100 before it counts.
    """
    if years_experience is None:
        years_experience = 50
    elif years_experience < 0:
        years_experience = 50
    else:
        years_experience = min(100, int(years_experience) * 10)

    degree_scores = {
        "none": 40,
        "foundation": 50,
        "bachelor": 60,
        "master": 70,
        "phd": 80,
    }
    if degree is None:
        degree = "bachelor"
    else:
        degree = str(degree).lower().strip()
    degree = degree_scores.get(degree, 50)

    if age is None:
        age = 50
    elif age < 18:
        age = 50
    else:
        age = min(100, int(age))

    if gaps_in_employment is None:
        gaps_in_employment = 50
    else:
        gaps_in_employment = max(0, 100 - int(gaps_in_employment) * 10)

    pc = parse_postcode(postcode)
    if pc in [c for codes in CITY_CODES.values() for c in codes]:
        postcode_score = 70
    elif pc:
        postcode_score = 50
    else:
        postcode_score = 50

    total = (
        years_experience * 0.35
        + degree * 0.25
        + age * 0.20
        + gaps_in_employment * 0.15
        + postcode_score * 0.05
    )

    return round(total)
```

